    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }
};

pub const OwnerPacked = packed struct(u32) {
    data: u30,
    kind: OwnerKind,

pub fn decode(self: OwnerPacked) FailureOwner {
            return (switch (self.kind) {
.none => FailureOwner{ .none = undefined },
.client => FailureOwner{ .client = IncrementalGraph(.client).FileIndex.init(self.data) },
.server => FailureOwner{ .server = IncrementalGraph(.server).FileIndex.init(self.data) },
.route => FailureOwner{ .route = RouteBundle.Index.init(self.data) },
});
    }
};

pub const FailureOwner = union(enum) {
    none: void,
    route: RouteBundle.Index,
    client: IncrementalGraph(.client).FileIndex,
    server: IncrementalGraph(.server).FileIndex,

pub fn encode(self: FailureOwner) OwnerPacked {
            return (switch (self) {
.none => OwnerPacked{ .kind = .none, .data = 0 },
.client => |data| OwnerPacked{ .kind = .client, .data = data.get() },
.server => |data| OwnerPacked{ .kind = .server, .data = data.get() },
.route => |data| OwnerPacked{ .kind = .route, .data = data.get() },
});
    }
    pub const Packed = OwnerPacked;
};

pub const FailureArrayHashContextViaOwner = struct {

pub fn hash(self: FailureArrayHashContextViaOwner, k: SerializedFailure) u32 {
            const self_ref = self;
            _ = &self_ref;
            return std.hash.int(@as(u32, @bitCast(k.getOwner().encode())));
    }

pub fn eql(self: FailureArrayHashContextViaOwner, a: SerializedFailure, b: SerializedFailure, _: usize) bool {
            const self_ref = self;
            _ = &self_ref;
            return (@as(u32, @bitCast(a.getOwner().encode())) == @as(u32, @bitCast(b.getOwner().encode())));
    }
};

pub const FailureArrayHashAdapter = struct {

pub fn hash(self: FailureArrayHashAdapter, owner_val: FailureOwner) u32 {
            const self_ref = self;
            _ = &self_ref;
            return std.hash.int(@as(u32, @bitCast(owner_val.encode())));
    }

pub fn eql(self: FailureArrayHashAdapter, a: FailureOwner, b: SerializedFailure, idx: usize) bool {
            const self_ref = self;
            _ = &self_ref;
            _ = &idx;
            return (@as(u32, @bitCast(a.encode())) == @as(u32, @bitCast(b.getOwner().encode())));
    }
};

pub const SerializedFailure = @This();

data: []u8,

pub fn deinit(self: *SerializedFailure, dev: *DevServer) void {
        _ = dev.allocator().free(self.data);
}

pub fn getOwner(self: SerializedFailure) Owner {
        return std.mem.bytesAsValue(OwnerPacked, self.data[0..4]).decode();
}

pub fn initFromLog(dev: *DevServer, owner: Owner, owner_display_name: []const u8, messages: []const bun.logger.Msg) !SerializedFailure {
        _ = assert((messages.len > 0));
        var sfb = std.heap.stackFallback(65536, dev.allocator());
        _ = &sfb;
        var payload = ((std.array_list.Managed(u8).initCapacity(sfb.get(), 65536)) catch unreachable);
        _ = &payload;
        const w = payload.writer();
        _ = try w.writeInt(u32, @bitCast(owner.encode()), .little);
        _ = try writeString32(owner_display_name, w);
        _ = try w.writeInt(u32, @intCast(messages.len), .little);
        for (cp_iter_slice(messages)) |msg| {
            _ = &msg;
            _ = try writeLogMsg((&msg), w);
        }
        const data = (if ((payload.items.ptr == (&sfb.buffer))) try dev.allocator().dupe(u8, payload.items) else payload.items);
        return SerializedFailure{ .data = data };
}

pub fn writeLogMsg(msg: *const bun.logger.Msg, w: Writer) !void {
        const kind_byte: u8 = (switch (msg.kind) {
.err => @intFromEnum(FailureErrorKind.bundler_log_err),
.warn => @intFromEnum(FailureErrorKind.bundler_log_warn),
.note => @intFromEnum(FailureErrorKind.bundler_log_note),
.debug => @intFromEnum(FailureErrorKind.bundler_log_debug),
.verbose => @intFromEnum(FailureErrorKind.bundler_log_verbose),
});
        _ = try w.writeByte(kind_byte);
        _ = try writeLogData(msg.data, w);
        const notes = msg.notes;
        _ = try w.writeInt(u32, @intCast(notes.len), .little);
        for (cp_iter_slice(notes)) |note| {
            _ = &note;
            _ = try writeLogData(note, w);
        }
}

pub fn writeLogData(data: bun.logger.Data, w: Writer) !void {
        _ = try writeString32(data.text, w);
        if (data.location) |loc| {
            _ = &loc;
            if ((loc.line < 0)) {
                _ = try w.writeInt(u32, 0, .little);
                return;
            }
            _ = assert((loc.column >= 0));
            _ = try w.writeInt(i32, @intCast(loc.line), .little);
            _ = try w.writeInt(u32, @intCast(loc.column), .little);
            _ = try w.writeInt(u32, @intCast(loc.length), .little);
            _ = try writeString32(((loc.line_text) orelse ("")), w);
        } else {
            _ = try w.writeInt(u32, 0, .little);
        }
}

pub fn writeString32(data: []const u8, w: Writer) !void {
        _ = try w.writeInt(u32, @intCast(data.len), .little);
        _ = try w.writeAll(data);
}
pub const Owner = FailureOwner;
pub const ArrayHashContextViaOwner = FailureArrayHashContextViaOwner;
pub const ArrayHashAdapter = FailureArrayHashAdapter;
pub const ErrorKind = FailureErrorKind;
